/** This is the id to be used to specify the modal root. */
const modalRootId = "__modal_root__";

/**
 * This guarantees the modal root to exist at the body root level
 */
export function ensureModalRoot(customId) {
  let modalRoot = null;
  const root = document.getElementById(customId || modalRootId);

  if (root instanceof HTMLDivElement) {
    modalRoot = root;
  } else {
    const body = document.getElementsByTagName("body")[0];
    modalRoot = document.createElement("div");

    if (body && modalRoot) {
      body.appendChild(modalRoot);
    }
  }

  if (modalRoot) {
    modalRoot.setAttribute(
      "style",
      `
      position: fixed;
      top: 0px;
      left: 0px;
      width: 100%;
      z-index: 999999;
    `
    );

    modalRoot.id = customId || modalRootId;
  }

  document.body.appendChild(modalRoot);
  return modalRoot;
}

/**
 * Guarantees the modal root is removed from the DOM.
 */
export function destroyModalRoot(customId) {
  const root = document.getElementById(customId || modalRootId);

  if (root instanceof HTMLDivElement) {
    const body = document.getElementsByTagName("body")[0];
    if (body) body.removeChild(root);
  }
}

/**
 * Peers within the potentially existing modal root and searches for the
 * specified class. If any divs with that class exists, they will be removed.
 */
export function destroyModalRootContent(className, customId) {
  const root = ensureModalRoot(customId);
  if (!root) return;
  const list = root.getElementsByClassName("vue-portal-target");

  for (let i = 0, iMax = list.length; i < iMax; ++i) {
    if (list[i].getElementsByClassName(className)) {
      root.removeChild(list[i]);
    }
  }
}
